package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Chapter-event refresh against real chapter data with controlled publication timing. */
public final class ReaderProgressUpdateChecks extends DeviceChecks {
 final AtomicInteger requests=new AtomicInteger(),active=new AtomicInteger(),maximum=new AtomicInteger();
 volatile JSONArray published;volatile boolean failure,liveResponse;volatile CountDownLatch gate=new CountDownLatch(0);
 @Override public void callActivityOnCreate(Activity activity,Bundle state){super.callActivityOnCreate(activity,state);if(activity instanceof ReaderActivity){ReaderActivity a=(ReaderActivity)activity;ReaderActivity.DirectorySource real=a.directorySource;a.directorySource=(book,force)->{if(!force)return real.fetch(book,false);requests.incrementAndGet();int count=active.incrementAndGet();maximum.accumulateAndGet(count,Math::max);CountDownLatch release=gate;JSONArray snapshot=published;boolean fail=failure,live=liveResponse;try{if(!release.await(30,TimeUnit.SECONDS))throw new IOException("test response gate timeout");if(fail)throw new IOException("controlled near-end failure");return live?real.fetch(book,true):snapshot;}finally{active.decrementAndGet();}};}}
 JSONArray prefix(JSONArray data,int count)throws Exception{JSONArray out=new JSONArray();for(int i=0;i<count;i++)out.put(data.getJSONObject(i));return out;}
 boolean visibleNotice(){return reader.notice!=null&&reader.notice.getVisibility()==View.VISIBLE;}
 void settled(int expected)throws Exception{waitFor(()->requests.get()==expected&&!reader.entryDirectoryLoading&&reader.pendingEntryDirectory==null,35,"directory request "+expected);assertTrue(!visibleNotice(),"silent directory check "+expected);}
 void next()throws Exception{int at=reader.index,token=reader.loadToken;waitFor(()->reader.layouts.containsKey(at+1),60,"next chapter layout ready");ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,at,f.totalChapters,f.layout,f.layout.pages.size()-1));reader.surface.turn(1);});waitFor(()->!reader.surface.animating()&&reader.index==at+1,5,"prepared cross-chapter turn");assertTrue(reader.loadToken==token&&!visibleNotice(),"chapter turn does not load synchronously");}
 void runChecks()throws Exception{
  String book="7616151491132279832";LocalLibrary db=new LocalLibrary(getTargetContext());JSONObject before=db.progress(book);JSONArray original=db.directory(book);Map<String,Long> times=new HashMap<>();try(android.database.Cursor c=db.getReadableDatabase().rawQuery("SELECT id,last_read FROM books",null)){while(c.moveToNext())times.put(c.getString(0),c.getLong(1));}
  try{
   JSONArray live=new NovelApi(getTargetContext(),db).directory(book,true);int oldCount=live.length()-5;JSONArray old=prefix(live,oldCount);published=old;db.directory(book,old);launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","大宋").putExtra("chapter_index",oldCount-7).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();waitFor(()->reader.bookPages!=null,35,"initial book pages");settled(1);record("entry_refresh_outside_last_five",true);
   ui(()->{reader.prepareNeighbors();reader.refreshDirectoryOnEntry();ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,f.chapterIndex,f.totalChapters,f.layout,Math.min(1,f.layout.pages.size()-1)));});assertTrue(requests.get()==1,"same chapter pages do not request directory");next();assertTrue(reader.directory.length()-reader.index==6&&requests.get()==1,"sixth from end does not refresh");record("same_chapter_and_sixth_from_end_do_not_refresh",true);
   next();settled(2);assertTrue(reader.directory.length()-reader.index==5,"fifth from end triggers exactly at threshold");record("fifth_from_end_checks_once",requests.get());
   ReaderPaginator current=reader.surface.frame.layout;published=prefix(live,oldCount+1);next();settled(3);assertTrue(reader.directory.length()==oldCount+1,"chapter entry discovers appended chapter");assertTrue(reader.surface.frame.layout!=current,"actual chapter changed");int anchor=reader.anchor;ReaderPaginator retained=reader.surface.frame.layout;waitFor(()->reader.layouts.containsKey(reader.index+1),30,"neighbor remains prepared");assertTrue(reader.anchor==anchor&&reader.surface.frame.layout==retained,"background append preserves layout and position");record("next_chapter_discovers_update_silently",reader.directory.length());
   liveResponse=true;next();settled(4);assertTrue(reader.directory.length()==live.length(),"real latest directory discovered after further publication");waitFor(()->{for(int i=1;i<=5;i++)if(!reader.library.hasChapter(book,reader.chapterId(reader.index+i)))return false;return true;},90,"new upcoming five cached");record("live_directory_update_warms_five",live.length());shot("progress-update-prepared");
   next();next();assertTrue(reader.directory.length()-reader.index==6&&requests.get()==4,"extended catalog moves reader outside refresh zone");next();settled(5);record("reenter_last_five_after_catalog_growth",true);
   int still=requests.get();ui(()->{reader.prepareNeighbors();reader.refreshDirectoryOnEntry();});SystemClock.sleep(65000);assertTrue(requests.get()==still,"no timed polling in last-five zone");record("last_five_idle_65_seconds_has_no_poll",requests.get());
   failure=true;next();settled(6);assertTrue(!reader.busy,"failed check leaves reader usable");ui(()->{reader.refreshDirectoryOnEntry();reader.prepareNeighbors();});assertTrue(requests.get()==6,"failure does not retry on same chapter");failure=false;next();settled(7);record("failure_is_silent_and_next_chapter_retries",true);
   gate=new CountDownLatch(1);next();waitFor(()->requests.get()==8&&reader.entryDirectoryLoading,5,"slow chapter request");next();assertTrue(requests.get()==8,"rapid chapter transition coalesces while request active");gate.countDown();settled(9);assertTrue(maximum.get()==1,"one background directory request at a time");record("inflight_transition_checks_latest_chapter_once",new JSONObject().put("requests",requests.get()).put("max_parallel",maximum.get()));shot("progress-update-latest");
  }finally{gate.countDown();if(reader!=null)ui(()->reader.finish());if(original!=null)db.directory(book,original);if(before!=null)db.progress(book,before.optString("chapter"),before.optInt("offset"),before.optInt("index"),before.optInt("total"),before.optString("title"));for(Map.Entry<String,Long> item:times.entrySet()){ContentValues value=new ContentValues();value.put("last_read",item.getValue());db.getWritableDatabase().update("books",value,"id=?",new String[]{item.getKey()});}}
  assertTrue(before==null||db.progress(book).toString().equals(before.toString()),"original position restored");record("reading_position_restored",true);
 }
 public void onStart(){output=new File(getTargetContext().getFilesDir(),"device-evidence");output.mkdirs();Bundle result=new Bundle();Throwable failure=null;try{runChecks();result.putString("stream","PASS "+checks.length()+" checks\n");}catch(Throwable e){failure=e;try{record("failure",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));}try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(output,"progress-update-results.json")),"UTF-8")){out.write(new JSONObject().put("device",Build.MODEL).put("success",failure==null).put("checks",checks).toString(2));}catch(Exception ignored){}finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
